import { config } from './config.js';
import { connectDB } from './db.js';
import * as models from './models/index.js';
import { buildServer } from './api/server.js';
import { createBot } from './bot/index.js';

await connectDB();
// make sure all indexes exist (incl. the unique ticket index)
for (const m of Object.values(models)) await m.createIndexes();

await models.Broadcast.updateMany({ status: 'SENDING' }, { status: 'INTERRUPTED' });

const app = await buildServer();
await app.listen({ port: config.port, host: '0.0.0.0' });
console.log(`API + app on http://localhost:${config.port}`);
if (config.devMode) console.log('⚠ DEV_MODE is ON - never use this on a real server.');

const bot = createBot();
if (bot) {
  bot
    .start({ onStart: (me) => console.log(`Bot @${me.username} is running`) })
    .catch((e) => console.error('Bot could not start (check BOT_TOKEN):', e.message));
} else {
  console.log('BOT_TOKEN not set - bot is OFF (the API still works).');
}

const stop = () => process.exit(0);
process.on('SIGINT', stop);
process.on('SIGTERM', stop);
